  let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  for(let y=0; y<H; y++) for(let xx=0; xx<W; xx++){
    const v = 128 + ((xx & 1) ? 7 : -7) + ((y % 3 === 0) ? -3 : 1) + (rnd() - .5) * 18, p = (y*W + xx)*4;
    d[p] = d[p+1] = d[p+2] = v; d[p+3] = 255;
  }
