  key.shadow.bias = -.0004; key.shadow.normalBias = .012; key.shadow.radius = 6;
  const fill = new THREE.DirectionalLight(0xffffff, .7); fill.position.set(-2.2, 1, 1.4);
  const rimL = new THREE.DirectionalLight(0xffffff, 1.0); rimL.position.set(1.6, 1.4, -2.4);   // contraluz: perfila la prenda
  const rimR = new THREE.DirectionalLight(0xfff4ea, .55); rimR.position.set(-1.8, .9, -2.0);
  scene.add(rimR);
  scene.add(key, key.target, fill, rimL, new THREE.HemisphereLight(0xffffff, 0x1a1a1a, .2));
