  geo.setAttribute('position', posA); geo.setAttribute('normal', norA); geo.setAttribute('uv', uvA); geo.setAttribute('color', colOf(G.aoO)); geo.setIndex(idxA);
  geo.addGroup(0, G.torsoCount, 0); geo.addGroup(G.torsoCount, G.index.length - G.torsoCount, 1);
  const geoIn = new THREE.BufferGeometry();
  geoIn.setAttribute('position', posA); geoIn.setAttribute('normal', norA); geoIn.setAttribute('uv', uvA); geoIn.setAttribute('color', colOf(G.aoI)); geoIn.setIndex(idxA);
  geoIn.groups = geo.groups.slice();

