      const a = I0[q]*3, b = I0[q+1]*3, c = I0[q+2]*3;
      const ux = P0[b]-P0[a], uy = P0[b+1]-P0[a+1], uz = P0[b+2]-P0[a+2], vx = P0[c]-P0[a], vy = P0[c+1]-P0[a+1], vz = P0[c+2]-P0[a+2];
