      const x = P0[v*3], y = P0[v*3+1], z = P0[v*3+2], t = clamp(y / yTop(x), 0, 1), a = tA(t), b = Math.max(.01, tB(t, z >= 0));
      const nx = Math.sign(x) * Math.pow(Math.abs(x) / a, T3.p - 1) / a, nz = Math.sign(z) * Math.pow(Math.abs(z) / b, T3.p - 1) / b;
