  const im = await loadImg(ref.norm), W = NORM_W, H = NORM_H, cv = document.createElement('canvas'); cv.width = W; cv.height = H;
  const x = cv.getContext('2d', { willReadFrequently:true }); x.drawImage(im, 0, 0, W, H);
