  const visorCv = document.createElement('canvas'); visorCv.width = 1024; visorCv.height = 256;
  const underCv = document.createElement('canvas'); underCv.width = 512; underCv.height = 128;
  const strapCv = document.createElement('canvas'); strapCv.width = 512; strapCv.height = 64;
  const T = cv => { const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = aniso; return t; };
  const crownTex = T(crownCv), visorTex = T(visorCv), underTex = T(underCv), strapTex = T(strapCv);
