  const crownMat = new THREE.MeshPhysicalMaterial(Object.assign({ map:crownTex, side:THREE.FrontSide }, fab));
  const innerMat = new THREE.MeshPhysicalMaterial(Object.assign({ side:THREE.BackSide }, fab));
  const visorMat = new THREE.MeshPhysicalMaterial(Object.assign({ map:visorTex, side:THREE.DoubleSide }, fab));
  const underMat = new THREE.MeshPhysicalMaterial(Object.assign({ map:underTex, side:THREE.DoubleSide }, fab));
  const strapMat = new THREE.MeshPhysicalMaterial(Object.assign({ map:strapTex, side:THREE.DoubleSide }, fab));
  const crown = new THREE.Mesh(crownGeo, crownMat), inner = new THREE.Mesh(crownGeo, innerMat);
  const visor = new THREE.Mesh(visorGeo, [visorMat, underMat]), strap = new THREE.Mesh(strapGeo, strapMat);
  strap.visible = false;                                // el cierre se pinta sobre la abertura
  const button = new THREE.Mesh(new THREE.SphereGeometry(.0075, 20, 12), crownMat.clone());
  button.scale.set(1, .45, 1); button.position.set(0, HC + .0015, 0); button.material.map = null;
  [crown, visor, strap, button].forEach(m => { m.castShadow = true; m.receiveShadow = true; });
  inner.receiveShadow = true;
  cap.add(crown, inner, visor, strap, button);

  // coordenadas "planas" de la copa (metros sobre la tela) para colocar el estampado sin distorsión
  const FX = new Float32Array((NU+1)*(NV+1)), FY = new Float32Array((NU+1)*(NV+1));
  const P3 = (i, j) => { const k = (j*(NU+1) + i)*3; return [cpos[k], cpos[k+1], cpos[k+2]]; };
