    x.fillStyle = rgb(mul(mesh, lite ? .62 : .45));         // agujeros de la malla
    for(let yy = 6; yy < H; yy += 13) for(let xx = m0 + ((yy / 13) % 2 ? 4 : 0); xx < m1; xx += 8){ x.beginPath(); x.ellipse(xx, yy, 2.4, 4.6, 0, 0, 2*Math.PI); x.fill(); }
    const grain = x.getImageData(0, 0, W, H), gd = grain.data;            // grano suave de la espuma
    for(let p=0; p<gd.length; p+=4){ const r = (Math.sin(p * 12.9898) * 43758.5453 % 1) * 6; gd[p] += r; gd[p+1] += r; gd[p+2] += r; }
