      const u = uOf(phi);
      x.strokeStyle = rgb(seam); x.lineWidth = 5; x.beginPath(); x.moveTo(u, 0); x.lineTo(u, H); x.stroke();
      x.setLineDash([9, 6]); x.strokeStyle = rgb(thread); x.lineWidth = 1.8;
