  const fill = new THREE.DirectionalLight(0xffffff, .7); fill.position.set(-2.2, 1, 1.4);
  const rimL = new THREE.DirectionalLight(0xffffff, 1.0); rimL.position.set(1.6, 1.4, -2.4);
  const rimR = new THREE.DirectionalLight(0xfff4ea, .55); rimR.position.set(-1.8, .9, -2.0);
